class Solution:
    def canBeIncreasing(self, nums: List[int]) -> bool:
        def increasing(skip):
            prev = None
            for i, x in enumerate(nums):
                if i == skip:
                    continue
                if prev is not None and prev >= x:
                    return False
                prev = x
            return True

        return any(increasing(r) for r in range(len(nums)))

