class Solution {
public:
    bool canBeIncreasing(vector<int>& nums) {
        auto increasing = [&](int skip) {
            int prev = 0;
            bool first = true;
            for (int i = 0; i < (int)nums.size(); ++i) {
                if (i == skip) continue;
                if (!first && prev >= nums[i]) return false;
                prev = nums[i];
                first = false;
            }
            return true;
        };
        for (int r = 0; r < (int)nums.size(); ++r)
            if (increasing(r)) return true;
        return false;
    }
};

