class Solution {
    public boolean canBeIncreasing(int[] nums) {
        for (int r = 0; r < nums.length; ++r)
            if (increasing(nums, r)) return true;
        return false;
    }

    private boolean increasing(int[] nums, int skip) {
        int prev = 0;
        boolean first = true;
        for (int i = 0; i < nums.length; ++i) {
            if (i == skip) continue;
            if (!first && prev >= nums[i]) return false;
            prev = nums[i];
            first = false;
        }
        return true;
    }
}

