class Solution:
    def canBeIncreasing(self, nums: List[int]) -> bool:
        removed = False
        for i in range(1, len(nums)):
            if nums[i] <= nums[i - 1]:
                if removed:
                    return False
                removed = True
                if i > 1 and nums[i - 2] >= nums[i]:
                    nums[i] = nums[i - 1]
        return True

